<script setup>
import MarkdownView from './MarkdownView.vue'
import { computed } from 'vue'
const props=defineProps({ outline: { type: Object, required: true } })
const audience=computed(()=>props.outline.metadata?.audiences?.length ? props.outline.metadata.audiences.join('、') : props.outline.collection.audience)
const categories = { ai:'AI 与大模型',engineering:'开发与工程',operations:'运维与自托管',productivity:'效率与工具',learning:'学习与成长',career:'职场与职业',life:'生活与经验',other:'其他' }
</script>
<template>
  <div class="collection-reader">
    <section class="page-hero collection-reading-hero"><img v-if="outline.metadata?.coverId" class="collection-cover" :src="`/api/collection-covers/${outline.metadata.coverId}`" alt="专题封面" @error="$event.target.hidden=true" /><span class="kicker">{{ outline.metadata?.category ? (categories[outline.metadata.category] || '其他') : '专题' }}</span><h1>{{ outline.collection.name || '未命名专题' }}</h1><p>{{ outline.collection.description }}</p><div class="cw-chips"><span v-for="tag in outline.metadata?.tags || []" :key="tag">{{ tag }}</span></div><div class="reading-goals"><p v-if="audience"><strong>适合谁</strong>{{ audience }}<small v-if="outline.collection.audience && outline.collection.audience !== audience">原适用人群：{{ outline.collection.audience }}</small></p><p v-if="outline.collection.goal"><strong>完成目标</strong>{{ outline.collection.goal }}</p></div><div class="collection-detail-meta"><span>{{ outline.collection.ownerName || '我' }} 创建</span><span>{{ outline.sections.length }} 个章节</span></div></section>
    <section class="section reading-section"><div class="reading-layout"><nav class="outline-nav" aria-label="专题目录"><span class="kicker">OUTLINE</span><a v-for="(section,i) in outline.sections" :key="i" :href="`#section-${section.id || i}`">{{ String(i+1).padStart(2,'0') }} {{ section.title }}</a></nav><main class="reading-content"><article v-for="(section,i) in outline.sections" :id="`section-${section.id || i}`" :key="i" class="reading-chapter" :class="`chapter-${(outline.metadata?.sectionLayouts?.[i] || 'LIST').toLowerCase()}`"><header><span>{{ String(i+1).padStart(2,'0') }}</span><div><h2>{{ section.title }}</h2><p v-if="section.description">{{ section.description }}</p></div></header><div v-if="!section.entries.length" class="empty-state">本章暂时没有内容。</div><div class="chapter-entries"><div v-for="(entry,j) in section.entries" :key="j" class="reading-entry" :class="`entry-${entry.kind.toLowerCase()}`"><template v-if="entry.kind==='NOTE'"><h3 v-if="entry.title">{{ entry.title }}</h3><MarkdownView class="entry-body" :source="entry.body || ''" /></template><template v-else-if="entry.kind==='POST'"><RouterLink v-if="entry.postId && entry.postTitle" :to="{path:'/',query:{post:entry.postId}}"><h3>{{ entry.postTitle }}</h3><p>{{ entry.postSummary }}</p><small>{{ entry.postAuthor }}</small></RouterLink><p v-else>原文已不可用</p></template><template v-else><a v-if="entry.externalUrl" :href="entry.externalUrl" target="_blank" rel="noopener noreferrer"><h3>{{ entry.title }} ↗</h3></a><p v-else>链接尚未填写</p></template><p v-if="entry.annotation && (entry.kind!=='POST' || entry.postId && entry.postTitle)" class="entry-annotation">{{ entry.annotation }}</p></div></div></article></main></div></section>
  </div>
</template>
<style scoped>
.collection-cover{display:block;width:100%;max-height:420px;aspect-ratio:16/9;object-fit:cover;border-radius:16px;margin-bottom:24px}.chapter-cards .chapter-entries{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:16px}.chapter-cards .reading-entry{padding:20px;border:1px solid var(--border,#ddd);border-radius:16px}.chapter-timeline .chapter-entries{border-left:2px solid var(--green,#276149);padding-left:24px}.chapter-timeline .reading-entry{position:relative}.chapter-timeline .reading-entry:before{content:'';position:absolute;left:-30px;top:24px;width:10px;height:10px;border-radius:50%;background:var(--green,#276149)}
</style>
